contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        address _requester,
        bytes32 _digest,
        uint256 _utxoSize,
        bytes memory _redeemerOutputScript,
        uint256 _requestedFee,
        bytes memory _outpoint
    ) public payable {
        bool statusBefore = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        bool ret = c.logRedemptionRequested(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint); if (__ESBMC_reverted()) return;
        bool statusAfter = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        assert(ret == statusBefore && statusAfter == statusBefore);
    }

    receive() external payable {}
}

