        c = new DepositLog();
    }

    function _run(address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint) internal {
        bool statusBefore;
        try c.approvedToLog(address(this)) returns (bool __r) { statusBefore = __r; } catch { return; }
        bool ret;
        try c.logRedemptionRequested(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint) returns (bool __r) { ret = __r; } catch { return; }
        bool statusAfter;
        try c.approvedToLog(address(this)) returns (bool __r) { statusAfter = __r; } catch { return; }
        assertTrue(ret == statusBefore && statusAfter == statusBefore);
    }

    function testFuzz_run(address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint) public {
